package com.atlashub.pay.ledger.application.commands.CreateBusinessAccount;
import com.atlashub.pay.ledger.domain.entities.*;import com.atlashub.pay.ledger.domain.repositories.*;import org.junit.jupiter.api.Test;import java.util.Optional;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class CreateBusinessAccountHandlerTest {@Test void createsOptionalBusinessAccountWithInitialSnapshot(){var accounts=mock(LedgerAccountRepository.class);var snapshots=mock(BalanceSnapshotRepository.class);when(accounts.nextIdentity()).thenReturn(5L);when(snapshots.nextIdentity()).thenReturn(6L);when(accounts.findByOrganizationIdAndEnvironmentAndAccountNameAndCurrency(anyLong(),any(),anyString(),any())).thenReturn(Optional.empty());when(accounts.findByOrganizationIdAndEnvironmentAndAccountTypeAndCurrency(anyLong(),any(),any(),any())).thenReturn(Optional.empty());when(accounts.save(any())).thenAnswer(i->i.getArgument(0));when(snapshots.save(any())).thenAnswer(i->i.getArgument(0));var result=new CreateBusinessAccountHandler(accounts,snapshots).execute(new CreateBusinessAccountCommand(1L,2L,"TEST","Payroll","PAYROLL_RESERVE","NGN"));assertEquals(5L,result.accountId());verify(accounts).save(any(LedgerAccount.class));verify(snapshots).save(any(BalanceSnapshot.class));}}
